const cfg = $input.first().json;
const body = cfg.body && typeof cfg.body === 'object' && !cfg.event && !cfg.content ? cfg.body : cfg;

const event = String(body.event || '');
const messageType = body.message_type;
const incoming = messageType === 'incoming' || messageType === 0 || messageType === '0' || messageType === undefined;
const content = String(body.content || body.processed_message_content || '').trim();
const conv = body.conversation || {};
const status = String(conv.status || '').toLowerCase();
const sender = body.sender || {};
const accountId = (body.account && body.account.id) || cfg.chatwoot_account_id;
const conversationId = conv.id || body.conversation_id;
const contactId = sender.id || conv.contact_id || (body.contact && body.contact.id);
const inboxId = conv.inbox_id || body.inbox_id;
const messageId = String(body.id || '');

const contactAttrs = (sender.custom_attributes && typeof sender.custom_attributes === 'object') ? sender.custom_attributes : {};
const convAttrs = (conv.custom_attributes && typeof conv.custom_attributes === 'object') ? conv.custom_attributes : {};

let skip = false;
let skip_reason = '';
if (event && event !== 'message_created') { skip = true; skip_reason = 'event'; }
else if (!incoming) { skip = true; skip_reason = 'outgoing'; }
else if (status === 'open' || status === 'resolved' || status === 'snoozed') { skip = true; skip_reason = 'human_or_closed'; }
else if (!content) { skip = true; skip_reason = 'empty'; }
else if (!conversationId || !accountId) { skip = true; skip_reason = 'missing_ids'; }

return [{
  json: {
    skip,
    skip_reason,
    text: content,
    event,
    status,
    message_id: messageId,
    account_id: accountId,
    conversation_id: conversationId,
    contact_id: contactId,
    inbox_id: inboxId,
    session_key: 'chatwoot:' + String(contactId || conversationId || 'anon'),
    redis_seen_key: 'buho:seen:' + messageId,
    redis_session_key: 'buho:session:' + String(contactId || conversationId || 'anon'),
    redis_outage_key: 'buho:outage:global',
    chatwoot_base_url: String(cfg.chatwoot_base_url || '').replace(/\/$/, ''),
    team_id_contabilidad: cfg.team_id_contabilidad,
    team_id_soporte: cfg.team_id_soporte,
    team_id_ventas: cfg.team_id_ventas,
    attrs_contact: contactAttrs,
    attrs_conv: convAttrs
  }
}];

function redisVal(item) {
  if (!item || !item.json) return '';
  const raw = item.json;
  const val = raw.value !== undefined ? raw.value : (raw.propertyName !== undefined ? raw.propertyName : raw.data);
  return val;
}

function normalizeAgent(v) {
  const a = String(v || '').toLowerCase().trim();
  if (a === 'facturacion' || a === 'ventas' || a === 'soporte') return a;
  return '';
}

const base = $('Normalize').first().json;
let redisSession = {};
try {
  const val = redisVal($('Redis Get Session').first());
  if (typeof val === 'string' && val) redisSession = JSON.parse(val);
  else if (val && typeof val === 'object') redisSession = val;
} catch (e) {}

let outage = '';
try {
  const ov = redisVal($('Redis Get Outage').first());
  if (typeof ov === 'string') outage = ov;
} catch (e) {}

const attrs = Object.assign({}, redisSession || {}, base.attrs_contact || {}, base.attrs_conv || {});
const convAgent = normalizeAgent((base.attrs_conv || {}).active_agent);
const redisAgent = normalizeAgent((redisSession || {}).active_agent);
const attrAgent = normalizeAgent(attrs.active_agent);
const active = convAgent || redisAgent || attrAgent || 'soporte';
const agent = (active === 'facturacion' || active === 'ventas') ? active : 'soporte';

const prevConv = String((redisSession && redisSession.conversation_id) || '');
const curConv = String(base.conversation_id || '');
let menuState = String((redisSession && redisSession.menu_state) || '');
let motivo = String((redisSession && redisSession.motivo) || '');
let tipoDocumento = String((redisSession && redisSession.tipo_documento) || '');
let tipoDocumentoNombre = String((redisSession && redisSession.tipo_documento_nombre) || '');
let numeroDocumento = String((redisSession && redisSession.numero_documento) || '');
let areaDestino = String((redisSession && redisSession.area_destino) || '');
let nombreCliente = String((redisSession && redisSession.nombre_cliente) || '');
let referencias = Array.isArray(redisSession && redisSession.referencias) ? redisSession.referencias : [];
let referenciaElegida = String((redisSession && redisSession.referencia) || attrs.referencia || '');
if (prevConv && curConv && prevConv !== curConv) {
  menuState = '';
  motivo = '';
  tipoDocumento = '';
  tipoDocumentoNombre = '';
  numeroDocumento = '';
  areaDestino = '';
  nombreCliente = '';
  referencias = [];
  referenciaElegida = String(attrs.referencia || '');
}

const session = {
  active_agent: agent,
  cedula: numeroDocumento || attrs.cedula || '',
  referencia: referenciaElegida,
  sn: attrs.sn || '',
  onu_id: attrs.onu_id || '',
  zona: attrs.zona || '',
  pending_action: attrs.pending_action || '',
  menu_state: menuState,
  motivo: motivo,
  conversation_id: curConv,
  tipo_documento: tipoDocumento,
  tipo_documento_nombre: tipoDocumentoNombre,
  numero_documento: numeroDocumento,
  area_destino: areaDestino,
  nombre_cliente: nombreCliente,
  referencias: referencias
};

const prompt = [
  'Mensaje del cliente:',
  base.text,
  '',
  'Sesión:',
  JSON.stringify(session),
  motivo ? ('Motivo elegido en menú: ' + motivo) : 'Sin motivo de menú.',
  outage ? ('DAÑO MASIVO activo: ' + outage) : 'Sin flag de daño masivo en Redis.'
].join('\n');

return [{
  json: Object.assign({}, base, {
    active_agent: agent,
    session,
    outage,
    text: prompt,
    user_text: base.text
  })
}];

