let prev = $('Router Menú').first().json;
try { if ($('Interpretar identidad').isExecuted) prev = $('Interpretar identidad').first().json; } catch (e) {}
try { if ($('Armar factura').isExecuted) prev = $('Armar factura').first().json; } catch (e) {}
const out = $input.first().json;
let reply = String(out.output !== undefined ? out.output : (out.text || '')).trim();
try {
  if ($('Respuesta Reinicio').isExecuted) {
    const onuMsg = $('Respuesta Reinicio').first().json || {};
    if (onuMsg.output) reply = String(onuMsg.output).trim();
  } else if ($('Respuesta Búsqueda').isExecuted) {
    const onuMsg = $('Respuesta Búsqueda').first().json || {};
    if (onuMsg.output) reply = String(onuMsg.output).trim();
  }
} catch (e) {}
if (!reply) reply = 'No pude generar una respuesta. Intenta de nuevo en un momento.';
if (reply.length > 4000) reply = reply.slice(0, 3900) + '\n…';

const session = Object.assign({}, prev.session || {});

function ran(name) {
  try { return $(name).isExecuted; } catch (e) { return false; }
}

function collectToolNames(obj, acc, depth) {
  if (!obj || typeof obj !== 'object' || depth > 8) return;
  if (Array.isArray(obj)) {
    obj.forEach((x) => collectToolNames(x, acc, depth + 1));
    return;
  }
  for (const [k, v] of Object.entries(obj)) {
    if ((k === 'tool' || k === 'toolName' || k === 'name') && typeof v === 'string') acc.push(v);
    if (k === 'action' && v && typeof v === 'object' && typeof v.tool === 'string') acc.push(v.tool);
    if (v && typeof v === 'object') collectToolNames(v, acc, depth + 1);
  }
}

if (ran('Transfer Ventas')) session.active_agent = 'ventas';
else if (ran('Transfer Facturación')) session.active_agent = 'facturacion';
else if (ran('Transfer Soporte desde Facturación') || ran('Transfer Soporte desde Ventas')) session.active_agent = 'soporte';
else {
  const names = [];
  collectToolNames(out.intermediateSteps || out.intermediate_steps || [], names, 0);
  const blob = names.join(' | ').toLowerCase();
  if (/\btransfer ventas\b/.test(blob)) session.active_agent = 'ventas';
  else if (/transfer factur/.test(blob)) session.active_agent = 'facturacion';
  else if (/transfer soporte/.test(blob)) session.active_agent = 'soporte';
}

let handoff_team = '';
if (ran('Handoff Ventas Humano')) handoff_team = 'ventas';
else if (ran('Handoff Contabilidad')) handoff_team = 'contabilidad';
else if (ran('Handoff Humano Soporte')) handoff_team = 'soporte';
else {
  const names = [];
  collectToolNames(out.intermediateSteps || out.intermediate_steps || [], names, 0);
  const blob = names.join(' | ').toLowerCase();
  if (/handoff ventas/.test(blob) || /\bhandoff:["']?ventas/.test(blob)) handoff_team = 'ventas';
  else if (/handoff contabilidad/.test(blob)) handoff_team = 'contabilidad';
  else if (/handoff humano soporte/.test(blob)) handoff_team = 'soporte';
}

let cfg = {};
try { cfg = $('Config').first().json || {}; } catch (e) {}
let norm = {};
try { norm = $('Normalize').first().json || {}; } catch (e) {}

const teamMap = {
  ventas: Number(cfg.team_id_ventas || prev.team_id_ventas || 0),
  contabilidad: Number(cfg.team_id_contabilidad || prev.team_id_contabilidad || 0),
  soporte: Number(cfg.team_id_soporte || prev.team_id_soporte || 0)
};
const handoff_team_id = handoff_team ? (teamMap[handoff_team] || 0) : 0;

const menu_items = Array.isArray(prev.menu_items) ? prev.menu_items : [];
const use_buttons = menu_items.length > 0 && cfg.menu_botones !== false && cfg.menu_botones !== 0 && String(cfg.menu_botones) !== 'false';

return [{
  json: {
    reply,
    account_id: prev.account_id || norm.account_id,
    conversation_id: prev.conversation_id || norm.conversation_id,
    contact_id: prev.contact_id || norm.contact_id,
    chatwoot_base_url: prev.chatwoot_base_url || cfg.chatwoot_base_url,
    redis_session_key: prev.redis_session_key || norm.redis_session_key,
    session_json: JSON.stringify(session),
    session,
    handoff_team,
    handoff_team_id,
    menu_items,
    use_buttons
  }
}];

const prev = $input.first().json;
const session = Object.assign({}, prev.session || {});
const userRaw = String(prev.user_text || '').trim();

function norm(s) {
  return String(s || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const user = norm(userRaw);

function numbered(intro, items) {
  const lines = items.map((it, i) => (i + 1) + '. ' + it.title);
  return intro.replace(/\s+$/, '') + '\n\n' + lines.join('\n');
}

function promptFor(sess) {
  return [
    'Mensaje del cliente:',
    prev.user_text || '',
    '',
    'Sesión:',
    JSON.stringify(sess),
    sess.motivo ? ('Motivo elegido en menú: ' + sess.motivo) : 'Sin motivo de menú.',
    sess.referencia ? ('Referencia elegida: ' + sess.referencia) : '',
    prev.outage ? ('DAÑO MASIVO activo: ' + prev.outage) : 'Sin flag de daño masivo en Redis.'
  ].filter(function (line) { return line !== ''; }).join('\n');
}

function clearIdentity() {
  session.tipo_documento = '';
  session.tipo_documento_nombre = '';
  session.numero_documento = '';
  session.area_destino = '';
  session.referencias = [];
  session.referencia = '';
  session.nombre_cliente = '';
  session.cedula = '';
  session.motivo = '';
  session.ultima_eleccion = '';
}

function elegido(label, text) {
  return 'Elegiste: ' + label + '\n\n' + text;
}

function menuResult(state, motivo, agent, reply, items) {
  session.menu_state = state;
  if (motivo !== null && motivo !== undefined) session.motivo = motivo;
  if (agent) session.active_agent = agent;
  return [{
    json: Object.assign({}, prev, {
      session: session,
      active_agent: session.active_agent,
      route: 'menu',
      output: reply,
      menu_items: items || [],
      text: promptFor(session)
    })
  }];
}

function agentResult(agent, motivo) {
  session.menu_state = 'done';
  if (motivo !== null && motivo !== undefined) session.motivo = motivo;
  if (agent) session.active_agent = agent;
  const copy = Object.assign({}, prev, {
    session: session,
    active_agent: session.active_agent,
    route: 'agente',
    menu_items: [],
    text: promptFor(session)
  });
  delete copy.output;
  return [{ json: copy }];
}

function buscarResult() {
  session.menu_state = 'buscando';
  session.ultima_eleccion = 'Sí';
  const copy = Object.assign({}, prev, {
    session: session,
    active_agent: session.active_agent,
    route: 'buscar_cliente',
    menu_items: [],
    text: promptFor(session)
  });
  delete copy.output;
  return [{ json: copy }];
}

const itemsMain = [
  { title: 'Soporte', value: 'Soporte' },
  { title: 'Consultar cuenta', value: 'Consultar cuenta' },
  { title: 'Ventas', value: 'Ventas' }
];
const itemsTipo = [
  { title: 'Cédula de ciudadanía', value: 'Cédula de ciudadanía' },
  { title: 'Cédula de extranjería', value: 'Cédula de extranjería' },
  { title: 'Pasaporte', value: 'Pasaporte' },
  { title: 'NIT', value: 'NIT' }
];
const itemsConfirma = [
  { title: 'Sí', value: 'Sí' },
  { title: 'No', value: 'No' }
