  message: 'Las fotos se envían en este turno. No inventes tarifas. No vuelvas a llamar esta tool salvo que el cliente lo pida.'
});

let sesion = '';
try { sesion = String($('Merge Session').first().json.session.cedula || '').trim(); } catch (e) {}
let body = {};
const raw = (typeof query === 'undefined') ? '' : query;
if (raw && typeof raw === 'object') body = raw;
else {
  const text = String(raw || '').trim();
  try { body = JSON.parse(text); } catch (e) { body = { cedula: text }; }
}
const cedula = sesion || String(body.cedula || '').trim();
const reboot = body.reboot === true || String(body.reboot).toLowerCase() === 'true';
if (!cedula) {
  return JSON.stringify({
    ok: false,
    cedula: '',
    reboot: false,
    message: 'Falta la cédula. Pídela. No inventes equipos ni digas que reiniciaste.'
  });
}
return JSON.stringify({
  ok: true,
  cedula: cedula,
  reboot: reboot,
