});

const agent = $input.first().json || {};
let pedir = false;
try { pedir = $('Enviar Fotos Planes').isExecuted; } catch (e) { pedir = false; }
return [{ json: Object.assign({}, agent, { enviar_fotos: pedir }) }];

const agent = $('Marcar fotos').first().json || {};
const sent = $input.first().json || {};
let reply = String(agent.output || '').trim();
const ok = !!sent.id || sent.message_type === 'outgoing';
if (!ok) {
  const aviso = 'No pude enviar las fotos de los planes en este momento.';
  reply = reply ? (reply + '\n\n' + aviso) : aviso;
}
if (!reply) reply = 'Estos son nuestros planes.';
return [{ json: { output: reply, intermediateSteps: agent.intermediateSteps || [] } }];

function parseTool(raw) {
  if (raw === undefined || raw === null || raw === '') return null;
  if (typeof raw === 'string') {
    try { return JSON.parse(raw); } catch (e) { return null; }
  }
  if (typeof raw === 'object') {
    if (typeof raw.response === 'string') {
      try { return JSON.parse(raw.response); } catch (e) { return raw; }
    }
    if (raw.ok !== undefined || raw.cedula !== undefined || raw.reboot !== undefined) return raw;
  }
  return null;
}

const agent = $input.first().json || {};
let ran = false;
try { ran = $('ONU por Cédula').isExecuted; } catch (e) { ran = false; }

let decision = null;
try { decision = parseTool($('ONU por Cédula').first().json); } catch (e) {}

const steps = Array.isArray(agent.intermediateSteps) ? agent.intermediateSteps : [];
if (!decision) {
  for (const step of steps) {
    const tool = String((step && step.action && step.action.tool) || '');
    const norm = tool.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    if (norm.indexOf('onu') !== -1 && norm.indexOf('cedula') !== -1) {
      ran = true;
      decision = parseTool(step.observation) || parseTool(step.action && step.action.toolInput);
    }
  }
}

let sesion = '';
try { sesion = String($('Merge Session').first().json.session.cedula || '').trim(); } catch (e) {}
const cedula = String((decision && decision.cedula) || sesion || '').trim();
const reboot = !!(decision && (decision.reboot === true || String(decision.reboot).toLowerCase() === 'true'));

if (!ran) {
  return [{ json: Object.assign({}, agent, { consultar_onu: false }) }];
}
if (!cedula || (decision && decision.ok === false)) {
  return [{ json: {
    output: (decision && decision.message) || 'Necesito tu cédula para buscar el equipo.',
    consultar_onu: false,
    intermediateSteps: steps
  } }];
}
return [{ json: {
  consultar_onu: true,
  cedula: cedula,
  reboot: reboot,
  output: agent.output || '',
  intermediateSteps: steps
} }];

const t = $('Marcar ONU').first().json || {};
const cedulaRaw = String(t.cedula || '').trim();
const cedula = cedulaRaw.toLowerCase();
const reboot = t.reboot === true || t.reboot === 'true';
const items = $input.all().map(i => i.json || {});
let onus = [];
for (const resp of items) {
  if (Array.isArray(resp.onus)) onus = onus.concat(resp.onus);
  else if (Array.isArray(resp)) onus = onus.concat(resp);
  else if (resp && resp.unique_external_id) onus.push(resp);
}

const failed = items.length > 0 && onus.length === 0 && items.every(r => r && r.error);
if (!cedula || failed) {
  return [{ json: {
    cedula: cedulaRaw,
    reboot_requested: reboot,
    count: 0,
    matches: [],
    do_reboot: false,
    reboot_onu_id: '',
    consulta_error: failed ? 'No pude consultar el equipo en este momento.' : ''
  } }];
}

const matches = onus
  .filter(o =>
    String(o.name || '').toLowerCase().includes(cedula) ||
    String(o.contact || '').toLowerCase().includes(cedula)
  )
  .map(o => ({
    name: o.name || '',
    unique_external_id: o.unique_external_id || '',
    sn: o.sn || '',
    olt_name: o.olt_name || '',
    status: o.status || o.onu_status || ''
  }));

const single = reboot && matches.length === 1;
return [{ json: {
  cedula: cedulaRaw,
  reboot_requested: reboot,
  count: matches.length,
  matches: matches,
  do_reboot: single,
  reboot_onu_id: single ? matches[0].unique_external_id : '',
  consulta_error: ''
} }];

const f = $('Filtrar por Cédula').first().json;
const r = $input.first().json || {};
const statusFalse = r.status === false || r.status === 'false' || !!r.error;
const ok = !statusFalse && (r.status === true || r.status === 'true' || !!r.response || !!r.message);
const onu = (f.matches && f.matches[0]) || {};
const detalle = (r.error && (r.error.message || r.error.description)) || '';
const message = ok
  ? 'Se envió el comando de reinicio a la ONU de ' + (onu.name || '') + ' (ID externo ' + (onu.unique_external_id || '') + ', SN ' + (onu.sn || '') + '). El equipo tardará 1-2 minutos en reconectar.'
  : 'No se pudo reiniciar el equipo.' + (detalle ? ' ' + String(detalle).slice(0, 160) : '');
let steps = [];
try { steps = $('Marcar ONU').first().json.intermediateSteps || []; } catch (e) {}
return [{ json: { output: message, result: ok ? 'reiniciada' : 'error', onu: onu, intermediateSteps: steps } }];

const f = $json;
let message;
if (f.consulta_error) {
  message = f.consulta_error;
} else if (f.count === 0) {
