  message = 'Encontré ' + f.count + ' equipos para la cédula ' + f.cedula + '. No reinicio cuando hay más de uno. ¿Cuál es el tuyo?\n' + list;
} else {
  const list = f.matches.map((o, i) => (i + 1) + '. ' + o.name + ' — ID externo ' + o.unique_external_id + ' — SN ' + o.sn + ' — OLT ' + o.olt_name + ' — estado ' + o.status).join('\n');
  message = 'Encontré ' + f.count + ' equipo(s) para la cédula ' + f.cedula + ':\n' + list;
}
let steps = [];
try { steps = $('Marcar ONU').first().json.intermediateSteps || []; } catch (e) {}
return [{ json: { output: message, count: f.count, matches: f.matches, intermediateSteps: steps } }];
